# Builds battles/somme/battle.json. Run from the repo root: python3 battles/somme/make.py
# Local metres from 50.0530N 2.7150E (x east, y north). The 22 km square holds the whole British front of 1 July 1916,
# from the 46th Division north of Gommecourt to the French XX Corps at Curlu and the Somme, Albert and the Tara-Usna
# line on the west and Bapaume in the north-east corner. Places are OpenStreetMap points as the research note gives them,
# kept in latitude and longitude and converted once; the woods, roads, the Ancre and the Somme are OpenStreetMap ways.
# The front lines from Gommecourt to Mametz are traced off three War Office 1:20,000 trench maps in the National
# Library of Scotland (57D.NE, trenches corrected to 16 May 1916; 57D.SE, to 28 April; 62D.NE, to 25 April), each
# fitted to today's churches to within about 30 m (62D.NE about 60 m), German trenches by their red and the British
# front line by its blue. Where those sheets show no line (the British line from Thiepval Wood to Fricourt, both lines
# from Carnoy to the Somme, the Gommecourt Park's north face) the note's traces stand, good to 150 to 250 m, and are
# labelled "about here". Clock times are the British and French clock, GMT+1; German sources run an hour ahead.
import json, math, re, datetime as dt
HERE = "battles/somme/"
LAT0, LON0 = 50.0530, 2.7150
KX, KY = 111320 * math.cos(math.radians(LAT0)), 111320  # tools/fetch_terrain.py's metres per degree
def M(lat, lon): return (round((lon - LON0) * KX), round((lat - LAT0) * KY))
HALF_EXTENT = 11000

# ---- terrain: chalk downland, no water drawn; the page reads a zero as a gap in the survey ----
T = json.load(open(HERE + "terrain.json"))
COLS, SP = T["cols"], T["spacing"]; HALF = COLS * SP / 2
assert abs(HALF - HALF_EXTENT) < 1, "terrain.json is not the battle's extent"
Z = [round(max(v, 0.1), 2) for v in T["z"]]
if Z != T["z"]: T["z"] = Z; json.dump(T, open(HERE + "terrain.json", "w"), separators=(",", ":"))
def z(x, y):
    c, r = int((x + HALF) / SP), int((HALF - y) / SP)
    return T["z"][r * COLS + c] if 0 <= c < COLS and 0 <= r < COLS else None
def on_land(p): return z(*p) is not None and z(*p) > 0

