def seg_near(a, b, p):  # nearest point to p on the segment a-b
    dx, dy = b[0] - a[0], b[1] - a[1]; L2 = dx * dx + dy * dy or 1
    f = max(0, min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / L2)); return (a[0] + f * dx, a[1] + f * dy)
def on_line(line, p): return min((seg_near(a, b, p) for a, b in zip(line, line[1:])), key=lambda q: math.dist(p, q))
def unit(a, b): d = math.dist(a, b) or 1; return ((b[0] - a[0]) / d, (b[1] - a[1]) / d)
def toward(p, line): return unit(p, on_line(line, p))  # the way from p square to a line
def step(p, u, d): return (p[0] + u[0] * d, p[1] + u[1] * d)
def back(p, d): return step(p, toward(p, GL), -d)  # d metres behind the British front, away from the Germans
def length(pts): return sum(math.dist(a, b) for a, b in zip(pts, pts[1:]))
def at_len(line, s):  # the point s metres along a line
    for a, b in zip(line, line[1:]):
        L = math.dist(a, b)
        if s <= L: return step(a, unit(a, b), s)
        s -= L
    return line[-1]
def len_at(line, p):  # how far along a line its point nearest p lies
    best, s0, bs = None, 0, 0
    for a, b in zip(line, line[1:]):
        q = seg_near(a, b, p); d = math.dist(p, q)
        if best is None or d < best: best, bs = d, s0 + math.dist(a, q)
        s0 += math.dist(a, b)
    return bs
def stretch(line, a, b, n):  # n points spread evenly along a line between the points nearest a and b, centres of n equal parts
    sa, sb = len_at(line, a), len_at(line, b)
    return [tuple(round(v) for v in at_len(line, sa + (sb - sa) * (k + 0.5) / n)) for k in range(n)]
def heading(a, b): return round(math.degrees(math.atan2(b[0] - a[0], b[1] - a[1])) % 360)

WOODS = {k: [M(*p) for p in v] for k, v in WOODS_LL.items() if k not in ('w117441411', 'w153301715', 'w142194389')}
