# Each division's frontage runs between two points on the line; its battalions stand in files, the leading battalion
# on the line, the rest behind it at the depths below. Which battalion led or followed is the note's; how a brigade's
# battalions shared its frontage is inferred.
DEPTH = (0, 120, 350, 600)
FRONTAGE = {  # division: (north end, south end, files north to south)
    '46': ((-5640, 10100), (-5330, 9200), [['sf5', 'sf6'], ['sf7', 'sf8'], ['ns6', 'ns5'], ['ss6', 'ss5']]),
    '56': ((-5050, 8550), (-4640, 8000), [['ls', 'kens'], ['rangers', 'l4'], ['qvr', 'qwr'], ['lrb', 'l2']]),
    '31': ((-4250, 6600), (-4180, 5420), [['yl12', 'yl13'], ['el11', 'yl14'], ['wy15', 'wy16', 'wy18', 'dli18']]),
    '4': ((-4190, 5380), (-4700, 4130), [['rw18', 'som1', 'sea2', 'lf2'], ['rb1', 'rw16', 'rdf2', 'essex2'], ['el1', 'hants1', 'rif1', 'ko1', ], ['rwar1', 'dwr2']]),
    '29': ((-4870, 3950), (-4560, 2250), [['rf2', 'rdf1'], ['lf1', 'mx16'], ['innis1', 'kosb1'], ['swb2', 'border1']]),
    '36N': ((-3980, 1650), (-3200, 1240), [['rif9'], ['rir12']]),
    '36': ((-2734, 940), (-2445, 445), [['rir11', 'rir8'], ['rir13', 'rir9'], ['innis9', 'innis11', 'rir10'], ['innis10', 'rir14', 'rir15']]),
    '32': ((-2480, 330), (-2390, -1300), [['nf16', 'lf16'], ['lf15', 'innis2'], ['hli16', 'koyli2'], ['hli17', 'border11', 'hli15']]),
    '8': ((-2287, -1700), (-2050, -3500), [['koyli8', 'yl9'], ['yl8', 'sf11'], ['berks2', 'rir1'], ['linc2', 'rb2'], ['mx2', 'wy2'], ['devon2', 'scr2']]),
    '34': ((-1900, -3700), (-760, -5650), [['nf20', 'nf23'], ['nf21', 'nf22'], ['linc10', 'suff11'], ['rs15', 'rs16']]),
    '21': ((-700, -5700), (-470, -6200), [['koyli9', 'dli15'], ['koyli10', 'ey1'], ['mx4', 'yl10'], ['som8', 'linc8']]),
    '17': ((-400, -6330), (150, -6950), [['wy10', 'gh7'], ['ey7', 'dorset6']]),
    '7': ((200, -6990), (2100, -7210), [['man20', 'rirish2'], ['rwf1', 'rwar2'], ['devon9', 'devon8'], ['gordon2', 'border2'], ['man22', 'queens2'], ['sst1', 'man21']]),
    '18': ((2200, -7215), (3700, -7270), [['rf11', 'northants6'], ['beds7', 'mx12'], ['norfolk8', 'essex10'], ['berks6', 'suff8'], ['queens7', 'rwk7'], ['buffs7'], ['esurrey8']]),
    '30': ((3800, -7290), (5700, -7900), [['kings18', 'gh2'], ['man19', 'wilts2'], ['kings17', 'kings19'], ['kings20', 'beds2']]),
}
POS = {}
for d, (a, b, files) in FRONTAGE.items():
    for spot, file in zip(stretch(BL, a, b, len(files)), files):
        for k, id in enumerate(file): POS[id] = tuple(round(v) for v in back(spot, DEPTH[k]))
# The Tyneside Irish on the Tara-Usna line a mile back; the 90th Brigade behind Maricourt; the 88th on St John's Road.
for id, p in zip(('nf27', 'nf26', 'nf25', 'nf24'), stretch(TARA_USNA, TARA_USNA[-1], TARA_USNA[0], 4)): POS[id] = p
for id, p in zip(('man16', 'man17', 'rsf2', 'man18'), [(4300, -8000), (4700, -8100), (5100, -8200), (4500, -8400)]): POS[id] = p
POS |= {'nfld': back(P['st_johns'], 230), 'essex1': back(P['st_johns'], 300), 'worc4': back(P['st_johns'], 700), 'hants2': back(P['st_johns'], 900)}
POS |= {'border11': back(DER['authuille_wood'], 0), 'dorset1': (-2750, -1500), 'lf19': (-2900, -1300), 'man2': (-3000, -1650)}
POS |= {'b167': (-5300, 7700), 'b138': (-6300, 9300), 'b143': back((-4400, 7300), 900), 'b92': (-5200, 5600), 'b146': (-4800, -1250), 'b147': (-4400, -900),
        'b148': (-5200, -1500), 'b56': (-4300, -5200), 'b57': (-4700, -5900), 'b58': (-5000, -5400), 'b62': (-1700, -6400), 'b51': (-1500, -7300),
        'b52': (-2000, -7700), 'b26': (2200, -9300), 'b27': (2700, -9200), 'bsa': (2400, -9600)}
FR_POS = {'fr153': (5900, -8150), 'fr39b': (6050, -8550), 'fr39c': (5300, -9000), 'fr11a': (6200, -9150), 'fr11b': (6350, -9650), 'fr11c': (5700, -9900)}
POS |= FR_POS
# The German battalions: two in the first position of each regiment's sector, one behind (the note: two forward, one back).
GSECTOR = {  # regiment: (north end, south end on the German front line, the support battalion's place)
    'r91': ((-5361, 10186), (-5100, 9500), (-4500, 10300)), 'r55': ((-5050, 9300), (-4750, 8950), P['gommecourt']),
    'i170': ((-4700, 8900), (-4127, 8161), DER['nameless']), 'i169': ((-4032, 7847), (-3946, 5750), P['serre']),
    'r121': ((-4045, 5307), (-4357, 3970), (-3500, 4400)), 'r119': ((-4495, 3584), (-3500, 2050), P['beaumont']),
    'r99': ((-2863, 1163), (-2046, 377), DER['stuff']), 'i180': ((-2345, -511), (-1574, -2534), P['mouquet']),
    'r110': ((-1457, -2769), (-740, -4974), P['contalmaison']), 'r111': ((-342, -5952), (391, -6795), centre(WOODS['r6631874'])),
    'r109': ((639, -6969), (2931, -7124), P['mametz']), 'i62': ((3359, -7069), (4646, -7013), P['montauban']),
    'b6': ((5003, -7013), (6504, -8349), DER['briqueterie']), 'i23': ((6600, -8900), (7148, -10019), (8300, -9300)),
}
for g, (a, b, sup) in GSECTOR.items():
    for k, p in enumerate(stretch(GL, a, b, 2)): POS[f"{g}_{k + 1}"] = tuple(round(v) for v in step(p, toward(p, BL), -80))
    if f"{g}_3" in BASE: POS[f"{g}_3"] = tuple(round(v) for v in sup)
POS |= {'r15': (-3600, 9300), 'i180r': (-300, 1000), 'i63': (6100, -5300), 'b8_1': (300, 3300), 'b8_2': (600, 3100), 'i185_1': P['irles'], 'i185_2': P['irles'],
        'bi16': (6500, -3600), 'r51': (9000, 1500), 'r38': (9300, 1200), 'r23': (9600, 900)}
HIDDEN_AT_START = {'b8_1', 'b8_2', 'i185_1', 'i185_2', 'bi16', 'r51', 'r38', 'r23', 'b56', 'b57', 'b58', 'b51', 'b52', 'b26', 'b27', 'bsa', 'r15', 'i180r'}
assert set(POS) == set(BASE), set(POS) ^ set(BASE)

# ---- movement ----
KEYS = {}
def K(t, p, **kw): return dict(t=t, x=round(p[0]), y=round(p[1]), **kw)
def carried(id, f): return next((k[f] for k in reversed(KEYS.get(id, [])) if f in k), {"state": "line", "strength": BASE[id][6]}.get(f))
def keys(id, ks):  # every leg starts where the unit stands, unless it is coming out of hiding
    have = KEYS.setdefault(id, [])
    if have and ks:
        a, b = have[-1], ks[0]
        assert carried(id, "state") == "hidden" or (a["x"], a["y"]) == (b["x"], b["y"]), (id, a["t"], b["t"], "a leg must start where the unit stands")
        if a["t"] == b["t"]: a.update({k: v for k, v in b.items() if k != "t"}); ks = ks[1:]
    have += ks
def last(id): k = KEYS[id][-1]; return (k["x"], k["y"])
def at(id, t, **kw): keys(id, [K(t, last(id), **kw)])  # a change in place
def appear(id, t, p, state="line", **kw): keys(id, [K(t, p, state=state, **kw)])
def hide(id, t): at(id, t, state="hidden")
PACE = 4  # km/h, a column of foot on the road
def walk(t0, pts, state="column", kmh=PACE):  # keys along a path at a marching pace
    pts = [p for i, p in enumerate(pts) if i == 0 or math.dist(p, pts[i - 1]) > 5]
    t, out = sec(t0), []
    for i, p in enumerate(pts):
        if i: t += math.dist(pts[i - 1], p) / (kmh / 3.6)
        out.append(K(fmt(t), p, h=heading(p, pts[i + 1]) if i + 1 < len(pts) else heading(pts[i - 1], p), **(dict(state=state) if i == 0 else {})))
    return out
def facing(id): return heading(POS[id], on_line(BL if BASE[id][1] == "german" else GL, POS[id]))

for id in BASE:
    appear(id, START, POS[id], state="hidden" if id in HIDDEN_AT_START else "line", h=facing(id))
for id in KEYS:
    if carried(id, "state") != "hidden" and sec(KEYS[id][-1]["t"]) < sec(END): at(id, END)

# ---- assemble and check ----
units = []
TOP = {"infantry": 6}  # km/h, the fastest any leg may go
for id, side, short, name, commander, type, strength, extra in OOB:
    ks, state = KEYS[id], None
    for a, b in zip(ks, ks[1:]):
        state = a.get("state", state)
        assert sec(b["t"]) > sec(a["t"]), (id, a["t"], b["t"])
        if state == "hidden": continue
        moved = (a["x"], a["y"]) != (b["x"], b["y"])
        assert not (moved and sec(b["t"]) - sec(a["t"]) > 3 * 3600), (id, a["t"], b["t"], "a march leg over three hours")
        kmh = math.dist((a["x"], a["y"]), (b["x"], b["y"])) / (sec(b["t"]) - sec(a["t"])) * 3.6
        assert kmh <= TOP[type], (id, a["t"], b["t"], f"{kmh:.1f} km/h")
    for k in ks: assert on_land((k["x"], k["y"])), (id, k["t"], "off the map")
    units.append(dict(id=id, side=side, name=name, short=short, commander=commander, type=type, strength=strength, keys=ks, **extra))

# ---- chapters: (time, title, text, camera centre, metres across, playback speed, when) ----
CHAPTERS = [
    (A("06:25"), "The last hour", "Seven days of bombardment end in an hour of it. At 6.25 the final barrage begins on the German trenches from Gommecourt to the Somme, 'an incessant roar of gun-fire'. Thirteen British divisions of the Fourth Army and of the Third Army's VII Corps stand in their trenches along 25 km of front, with the French XX Corps on their right.", [0, 0], 22000, 60, "6.25 a.m."),
]
events = [dict(t=t, title=a, text=b, at=at_, view=v, speed=s, **({"when": w} if w else {})) for t, a, b, at_, v, s, w in CHAPTERS]
for e in events:  # without `when` the card speaks the nearest hour (app.js chapterWhen), so it must be near the frame's clock
    s = sec(e["t"]) % 86400; hh = [n % 12 or 12 for n in (int(s // 3600), int(s // 3600) + 1)]; num = re.search(r"\d+", e.get("when", ""))
    assert not num or int(num[0]) in hh, (e["t"], e["when"], "the card's hour is not the frame's")
    assert "when" in e or abs(s - math.floor(s / 3600 + 0.5) * 3600) <= 15 * 60, (e["t"], e["title"], "give it a when")

battle = dict(
    id="somme", name="The First Day on the Somme", date="1916-07-01", dateText="1 July 1916", place="The Somme, Picardy, France",
    origin=dict(lat=LAT0, lon=LON0), extent=2 * HALF_EXTENT, start=START, end=END, sunrise="04:43", sunset="21:02", speed=60, lapse=3600, menPerDot=20,
    water=0, terrainExaggeration=2, contourInterval=5, trees=dict(density=0.003), fields=FIELDS, wind=dict(x=0.6, y=0.2), view=dict(x=0, y=0, width=22000),
    sides=dict(british=dict(name="British (Fourth Army, Rawlinson; VII Corps of the Third Army)", color="#3a5f9e", light="#7d9bd0", dark="#1d3561"),
               french=dict(name="French (Sixth Army, Fayolle: XX Corps)", color="#6d8fb5", light="#a9c0dc", dark="#36506e"),
               german=dict(name="Germans (2nd Army, von Below: XIV Reserve Corps, von Stein)", color="#4a4a42", light="#8c8c80", dark="#22221e")),
    features=features, units=units, events=events,
    sources=[
        "Brig.-Gen. Sir James E. Edmonds, <i>Military Operations France and Belgium, 1916</i>, vol. I, <i>Sir Douglas Haig's Command to the 1st July: Battle of the Somme</i> (London: Macmillan, 1932), chapters XII to XIX and the order of battle: the official history, written from the war diaries.",
        "Wikipedia, \"First day on the Somme\" and its pages on the capture of Montauban, Mametz, Fricourt and La Boisselle, the Gommecourt salient, the Schwaben Redoubt, the Leipzig Salient, the Hawthorn Ridge Redoubt, the mines, the Royal Newfoundland Regiment, the 31st Division and the Thiepval Memorial, for the times and German losses they quote from Edmonds, Sheldon and Whitehead.",
        "The Long, Long Trail, the orders of battle of the 4th, 7th, 8th, 17th, 18th, 21st, 29th, 30th, 32nd, 34th, 36th, 46th and 56th Divisions, and \"Time on the Western Front\".",
        "War Office (G.S.G.S. 2742), trench maps 57D.NE edition 2B (trenches corrected to 16 May 1916), 57D.SE edition 2B (28 April 1916) and 62D.NE edition 2B (25 April 1916), 1:20,000, National Library of Scotland, <a href='https://maps.nls.uk/ww1/trenches/' target='_blank'>British First World War Trench Maps</a> (CC-BY): the front lines from Gommecourt to Mametz.",
        "Woods, roads, rivers, craters and places from OpenStreetMap (ODbL).",
        "Terrain: " + T["source"] + ", 30 m, sampled to 31 m.",
    ],
)
json.dump(battle, open(HERE + "battle.json", "w"), indent=1, ensure_ascii=False)
